script:
test("weekend between Thursday Friday and Monday absences does not break a streak of 3", function () {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-08");
});

test("present day after two absences never reaches 3", function () {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "present" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), null);
});

test("four absences in a row returns the third day not the fourth", function () {
  var days = [
    { date: "2024-01-08", status: "absent" },
    { date: "2024-01-09", status: "absent" },
    { date: "2024-01-10", status: "absent" },
    { date: "2024-01-11", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-10");
});

test("two separate streaks of 3 return only the first date", function () {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "absent" },
    { date: "2024-01-09", status: "present" },
    { date: "2024-01-10", status: "absent" },
    { date: "2024-01-11", status: "absent" },
    { date: "2024-01-12", status: "absent" },
    { date: "2024-01-15", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-08");
});

test("empty list returns nothing", function () {
  assert.equal(code.firstThreeDayAbsenceStreak([]), null);
});

test("a single absence stays below 3", function () {
  var days = [
    { date: "2024-06-03", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), null);
});

test("exactly two absences and the list ends stays below 3", function () {
  var days = [
    { date: "2024-01-08", status: "absent" },
    { date: "2024-01-09", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), null);
});

test("a present day resets a count of 2 so the next absence stays at 1", function () {
  var days = [
    { date: "2024-01-08", status: "absent" },
    { date: "2024-01-09", status: "absent" },
    { date: "2024-01-10", status: "present" },
    { date: "2024-01-11", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), null);
});

test("the third absence on the last day is returned", function () {
  var days = [
    { date: "2024-01-02", status: "present" },
    { date: "2024-01-03", status: "absent" },
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-05");
});

test("a later absence does not replace the earlier date the streak reached 3", function () {
  var days = [
    { date: "2024-01-02", status: "present" },
    { date: "2024-01-03", status: "absent" },
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "present" },
    { date: "2024-01-09", status: "absent" },
    { date: "2024-01-10", status: "present" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-05");
});

test("a present day resets the count and a later weekend gap does not stop the next streak", function () {
  var days = [
    { date: "2024-01-02", status: "absent" },
    { date: "2024-01-03", status: "absent" },
    { date: "2024-01-04", status: "present" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "absent" },
    { date: "2024-01-09", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-09");
});

test("leap day is returned when it is the third absent day", function () {
  var days = [
    { date: "2024-02-27", status: "absent" },
    { date: "2024-02-28", status: "absent" },
    { date: "2024-02-29", status: "absent" },
    { date: "2024-03-01", status: "present" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-02-29");
});

test("the third absence on the first of the next month is returned", function () {
  var days = [
    { date: "2024-01-30", status: "absent" },
    { date: "2024-01-31", status: "absent" },
    { date: "2024-02-01", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-02-01");
});

test("the third absence on the last day of the month is returned", function () {
  var days = [
    { date: "2024-01-29", status: "absent" },
    { date: "2024-01-30", status: "absent" },
    { date: "2024-01-31", status: "absent" },
    { date: "2024-02-01", status: "present" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-31");
});

test("a year change does not break three absences across December and January", function () {
  var days = [
    { date: "2023-12-28", status: "absent" },
    { date: "2023-12-29", status: "absent" },
    { date: "2024-01-01", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-01");
});

test("a four calendar day gap with the missing school day already removed does not break the streak", function () {
  var days = [
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-09", status: "absent" },
    { date: "2024-01-10", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-10");
});
